from openpyxl.utils import column_index_from_string
from collections import deque

def coord_to_indices(coord):
    for i,ch in enumerate(coord):
        if ch.isdigit():
            return (int(coord[i:]), column_index_from_string(coord[:i]))

cell_map2 = {}
for coord, info in map_data2.items():
    rc = coord_to_indices(coord)
    cell_map2[rc] = {'value': info['value'], 'color': info['color']}

DIRECTIONS = {'up':(-2,0),'down':(2,0),'left':(0,-2),'right':(0,2)}
start = (1,1)
max_row, max_col = 20, 9
queue = deque([(1,1,0,None)])
visited = set()
final_cell = None
while queue:
    r,c,m,pd = queue.popleft()
    if m == 11:
        final_cell = (r,c)
        break
    for dname,(dr,dc) in DIRECTIONS.items():
        if pd and ((pd=='up' and dname=='down') or (pd=='down' and dname=='up') or (pd=='left' and dname=='right') or (pd=='right' and dname=='left')):
            continue
        nr,nc = r+dr, c+dc
        if 1<=nr<=max_row and 1<=nc<=max_col:
            state = (nr,nc,m+1,dname)
            if state not in visited:
                visited.add(state)
                queue.append(state)
print('Final after 11 moves:', final_cell)
print('Color:', cell_map2.get(final_cell,{}).get('color'))
